import { NextResponse } from "next/server"; import { requirePermission } from "@/lib/auth/guards"; import { createSupabaseServerClient } from "@/lib/supabase/server"; import { monthlyCsv } from "@/lib/reports/monthly-csv"; import { demoMode, demoUnits } from "@/lib/demo/mode";
export async function GET(request:Request){try{await requirePermission("export_reports");const u=new URL(request.url);const month=u.searchParams.get("month");const scope=u.searchParams.get("scope");if(!month||!/^\d{4}-\d{2}$/.test(month)||!['unit','fleet'].includes(scope??''))return NextResponse.json({error:{code:"INVALID_PARAMS",message:"Choose a valid month and report scope"}},{status:400});const unitId=scope==='unit'?u.searchParams.get("unitId"):null;if(demoMode)return new NextResponse(monthlyCsv(month,demoUnits.map((unit)=>({month,unit_body_number:unit.body_number,remittance_due_centavos:18000,remittance_paid_centavos:18000,outstanding_centavos:0,total_expense_centavos:0,net_income_centavos:18000}))),{headers:{"content-type":"text/csv; charset=utf-8"}});const s=await createSupabaseServerClient();const {data,error}=await s.rpc("monthly_report",{month_start:`${month}-01`,selected_unit_id:unitId});if(error)throw error;return new NextResponse(monthlyCsv(month,data??[]),{headers:{"content-type":"text/csv; charset=utf-8","content-disposition":`attachment; filename="rolnet-${month}-${scope}.csv"`}});}catch{return NextResponse.json({error:{code:"FORBIDDEN",message:"Owner report access is required"}},{status:403});}}
